if(g.mode==="starcatch")return shell("スターキャッチ",`<h1>⭐ スターキャッチ</h1><p>星をタップして集めよう！</p><div id="stars" class="row"></div><p id="score">星：0</p><button onclick="start()">新しいラウンド</button>`,`let n=0;function start(){n=0;stars.innerHTML=Array.from({length:12},(_,i)=>'<button style="font-size:26px" onclick="this.textContent=\'✨\';this.disabled=true;score.textContent=\'星：'+(++n)+'\'">⭐</button>').join('');score.textContent='星：0'}start();`);
if(g.mode==="maze")return shell("迷路チャレンジ",`<h1>🧭 迷路チャレンジ</h1><p>スタートからゴールまで進もう！</p><div id="maze" class="grid" style="grid-template-columns:repeat(5,42px)"></div><div class="row"><button onclick="move(-5)">⬆</button><button onclick="move(-1)">⬅</button><button onclick="move(5)">⬇</button><button onclick="move(1)">➡</button></div><p id="msg">青いマスがあなた</p>`,`let pos=0,walls=[1,3,6,8,11,13,16,18];function draw(){maze.innerHTML=Array.from({length:25},(_,i)=>'<div class="tile" style="width:42px;height:42px;background:'+(i===pos?'#ffe78a':walls.includes(i)?'#555':'#fff')+';color:#5545d3">'+(i===pos?'🙂':i===24?'🏁':walls.includes(i)?'⬛':'')+'</div>').join('')}function move(d){let n=pos+d;if(n<0||n>24||(d===1&&pos%5===4)||(d===-1&&pos%5===0)||walls.includes(n))return;pos=n;draw();if(pos===24)msg.textContent='ゴール！クリア！'}draw();`);
