if(g.mode==="island")return shell("無人島サバイバル",`<h1>🏝️ 無人島サバイバル</h1><p>行動を選んで食料と体力を保とう！</p><p id="stats">体力 5 / 食料 3</p><div class="row"><button onclick="act('fish')">🎣 魚をとる</button><button onclick="act('rest')">😴 休む</button><button onclick="act('explore')">🧭 探索</button></div><p id="msg">7日間生き残ろう</p>`,`let hp=5,food=3,day=1;function act(a){if(a==='fish')food+=2;if(a==='rest')hp=Math.min(5,hp+1);if(a==='explore'){if(Math.random()>.5)food++;else hp--}food--;day++;stats.textContent='体力 '+hp+' / 食料 '+food;if(hp<=0||food<0||day>7){msg.textContent=day>7?'島から脱出成功！':'サバイバル失敗！';return}msg.textContent=' '+day+'日目。次の行動を選ぼう'} `);
