if(g.mode==="river")return shell("川くだり",`<h1>🛶 川くだり</h1><p>岩を避けながら川を下ろう！</p><div class="big" id="boat">🛶</div><div class="row"><button onclick="steer(-1)">左</button><button onclick="steer(1)">右</button></div><p id="score">距離：0</p><button onclick="start()">スタート</button>`,`let lane=1,d=0,run=false,it;function steer(x){lane=Math.max(0,Math.min(2,lane+x));boat.textContent=['🛶','🛶','🛶'][lane]}function start(){d=0;run=true;clearInterval(it);it=setInterval(()=>{d++;score.textContent='距離：'+d;if(Math.random()<.25&&Math.floor(Math.random()*3)===lane){run=false;clearInterval(it);boat.textContent='💦';score.textContent='岩に衝突！距離 '+d}},600)}start();`);
