if(g.mode==="temple")return shell("古代神殿",`<h1>🏛️ 古代神殿</h1><p>正しい順番で紋章を押して扉を開こう！</p><div id="symbols" class="row"></div><p id="msg">順番を覚えて入力！</p><button onclick="start()">新しい謎</button>`,`let seq=[],input=[];function start(){seq=Array.from({length:3},()=>Math.floor(Math.random()*4));input=[];symbols.innerHTML=['☀️','🌙','⭐','🔥'].map((v,i)=>'<button style="font-size:25px" onclick="press('+i+')">'+v+'</button>').join('');msg.textContent='順番：'+seq.map(i=>['☀️','🌙','⭐','🔥'][i]).join(' → ')+' を覚えてね'}function press(i){input.push(i);if(input.length===3){msg.textContent=input.every((v,j)=>v===seq[j])?'扉が開いた！クリア！':'違う順番！もう一度挑戦';}}start();`);
