if(g.mode==="spell")return shell("スペルキャスター",`<h1>✨ スペルキャスター</h1><p>魔法の名前と同じ紋章を選ぼう！</p><div class="big" id="spell">炎の魔法</div><div id="opts" class="row"></div><p id="score">正解：0</p><button onclick="next()">次の魔法</button>`,`let n=0,q=[['炎の魔法','🔥'],['水の魔法','💧'],['森の魔法','🌳'],['雷の魔法','⚡']];function next(){let x=q[Math.floor(Math.random()*q.length)];spell.textContent=x[0];opts.innerHTML=q.map(v=>'<button onclick="pick(\\''+v[1]+'\\',\\''+x[1]+'\\')">'+v[1]+'</button>').join('')}function pick(a,b){if(a===b)n++;score.textContent='正解：'+n;next()}next();`);
if(g.mode==="dragon")return shell("ドラゴン育成",`<h1>🐉 ドラゴン育成</h1><p>ごはんと遊びでドラゴンを育てよう！</p><div class="big" id="dragon">🥚</div><p id="stats">なかよし度：0</p><div class="row"><button onclick="care(1)">🍖 ごはん</button><button onclick="care(2)">🎾 遊ぶ</button><button onclick="care(3)">💤 休ませる</button></div>`,`let n=0;function care(x){n+=x;dragon.textContent=n>15?'🐉':n>7?'🐲':'🥚';stats.textContent='なかよし度：'+n+(n>15?' 成長したよ！':'')}`);
