function openGame(g){$("gameTitle").textContent=g.name;$("gameFrame").srcdoc=categoryGameDocument(g);$("gameModal").hidden=false;document.body.style.overflow="hidden"}
function closeGame(){$("gameModal").hidden=true;$("gameFrame").src="about:blank";$("gameFrame").srcdoc="";document.body.style.overflow=""}
$("closeGame").addEventListener("click",closeGame);$("gameModal").addEventListener("click",e=>{if(e.target===$("gameModal"))closeGame()});$("fullscreenButton").addEventListener("click",()=>{const f=$("gameFrame");if(f.requestFullscreen)f.requestFullscreen()});document.addEventListener("keydown",e=>{if(e.key==="Escape"&&!$("gameModal").hidden)closeGame()});
render();


// GAME PARK polish: quick play, keyboard shortcuts, and accessible feedback.
(function(){
  const randomButton=document.getElementById("randomGame");
  if(randomButton) randomButton.addEventListener("click",()=>{
    const choices=games.filter(g=>g.mode);
    if(choices.length) openGame(choices[Math.floor(Math.random()*choices.length)]);
  });
  document.addEventListener("keydown",e=>{
    if(e.key==="/" && !["INPUT","TEXTAREA"].includes(document.activeElement.tagName)){
      e.preventDefault();document.getElementById("searchInput")?.focus();
    }
  });
  const search=document.getElementById("searchInput");
  if(search) search.setAttribute("autocomplete","off");
})();
